 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <div id="app"></div>

   <script>
     const fields = [
       {
         id: "fullName",
         name: "fullName",
         label: "Full name",
         type: "text",
         autocomplete: "name",
         placeholder: "Alex Morgan",
         required: true,
         messages: {
           required: "Enter your full name."
         }
       },
       {
         id: "email",
         name: "email",
         label: "Email address",
         type: "email",
         autocomplete: "email",
         placeholder: "alex@example.com",
         required: true,
         messages: {
           required: "Enter your email address.",
           pattern: "Enter an email address in the format name@example.com."
         }
       },
       {
         id: "phone",
         name: "phone",
         label: "Phone number",
         type: "tel",
         autocomplete: "tel",
         placeholder: "555-123-4567",
         required: false,
         helper: "Use 10 digits, with optional spaces, dashes, parentheses, or a leading country code.",
         messages: {
           pattern: "Enter a phone number with 10 to 15 digits, using only numbers, spaces, dashes, parentheses, or a leading plus sign."
         }
       }
     ];

     function Field({ id, name, label, type, autocomplete, placeholder, required, helper }) {
       const helperId = helper ? `${id}-helper` : "";
       const errorId = `${id}-error`;
       const describedBy = [helperId, errorId].filter(Boolean).join(" ");
       const requiredMarker = required ? ' <span class="required-marker" aria-hidden="true">*</span>' : "";

       return `
         <div class="form-field">
           <label for="${id}">${label}${requiredMarker}</label>
           <input
             id="${id}"
             name="${name}"
             type="${type}"
             autocomplete="${autocomplete}"
             placeholder="${placeholder}"
             ${required ? "required" : ""}
             aria-describedby="${describedBy}"
           >
           ${helper ? `<p class="helper-text" id="${helperId}">${helper}</p>` : ""}
           <p class="error-message" id="${errorId}"></p>
         </div>
       `;
     }

     function SupportContactForm() {
       return `
         <main id="main-content" class="page-shell" tabindex="-1">
           <header>
             <p class="eyebrow">Support team</p>
             <h1>Contact support</h1>
             <p class="intro">Tell us how to reach you and our support team will follow up with next steps.</p>
           </header>

           <section class="card" aria-labelledby="support-form-heading">
             <h2 id="support-form-heading">Support request contact details</h2>
             <p class="required-note"><span class="required-marker">*</span> indicates a required field.</p>
             <form id="support-form" novalidate>
               ${fields.map(Field).join("")}
               <button type="submit">Submit support request</button>
               <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
             </form>
           </section>
         </main>
       `;
     }

     function isValidEmail(value) {
       return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
     }

     function isValidPhone(value) {
       if (!value) {
         return true;
       }

       const allowedCharacters = /^\+?[0-9\s().-]+$/.test(value);
       const digitCount = value.replace(/\D/g, "").length;
       return allowedCharacters && digitCount >= 10 && digitCount <= 15;
     }

     function setError(input, message) {
       const error = document.getElementById(`${input.id}-error`);
       input.setAttribute("aria-invalid", message ? "true" : "false");
       error.textContent = message;
     }

     function validateField(input) {
       const field = fields.find((item) => item.id === input.id);
